inputParameters.queryExpression:
def text(d; m): if type == "string" and length > 0 then .[0:m] else d end;
def obj: if type == "object" then . else {} end;
def int: floor % 1000000000000000;
def cents: if type == "number" and . >= 0 and . <= 99999999999 then int else 0 end;
def qty: if type == "number" and . >= 1 then (if . > 99 then 99 else int end) else 1 end;

(.order | obj) as $o
| {
    orderId: ($o.orderId | text("CC-UNKNOWN"; 40)),
    seed: ($o.seed | if type == "number" then (if . < 0 then -. else . end | int) % 1000000 else 0 end),
    placedAt: ($o.placedAt | text("at a time nobody wrote down"; 40)),
    customer: ($o.customer | obj | {
      name: (.name | text("Valued Customer #7"; 80)),
      email: (.email | text(""; 120))
    }),
    lines: [
      ($o.lines | if type == "array" then .[0:50] else [] end)[]
      | select(type == "object")
      | {
          id: (.id | text("mystery-item"; 60)),
          name: (.name | text("Mystery Item"; 120)),
          emoji: (.emoji | text("📦"; 16)),
          qty: (.qty | qty),
          unitPriceCents: (.unitPriceCents | cents)
        }
    ],
    coupon: ($o.coupon | text(""; 40)),
    shipping: ($o.shipping | obj | {
      id: (.id | text("pigeon"; 30)),
      label: (.label | text("Carrier Pigeon"; 80)),
      priceCents: (if (.priceCents | type) == "number" then (.priceCents | cents) else 1200 end),
      eta: (.eta | text("3 to 900 business days"; 160))
    }),
    payment: ($o.payment | obj | {
      id: (.id | text("handshake"; 30)),
      label: (.label | text("A firm handshake"; 80))
    })
  }

def int: ceil % 1000000000000000;
def pct(p): (. * p / 100) | int;

.cart as $c
| ([$c.lines[] | .qty * .unitPriceCents] | add // 0) as $subtotal
| ([$c.lines[] | select(.qty >= 3) | .qty * .unitPriceCents] | add // 0) as $bulk
| (
    [
      (if ($c.lines | length) == 0
        then {label: "Empty Cart Handling Fee", amountCents: 499, note: "Carrying nothing is harder than it looks."}
        else empty end),
      (if $bulk > 0
        then {label: "Bulk Purchase Surcharge (5%)", amountCents: ($bulk | pct(5)), note: "Buy more, pay more."}
        else empty end),
      (if ($c.coupon | length) > 0
        then {label: "Coupon \"\($c.coupon)\" Redemption Fee (10%)", amountCents: ($subtotal | pct(10)), note: "Coupons are a premium feature."}
        else empty end),
      {label: "Convenience Fee", amountCents: 499, note: "For your convenience."},
      {label: "Inconvenience Fee", amountCents: 499, note: "For ours."},
      {label: "Shipping: \($c.shipping.label)", amountCents: $c.shipping.priceCents, note: $c.shipping.eta},
      {label: "Tax (13.37%, vibes-based)", amountCents: ($subtotal * 1337 / 10000 | int), note: "We asked around."}
    ]
  ) as $fees
| ($fees + [
    {label: "Fee Processing Fee (3% of fees)", amountCents: (([$fees[].amountCents] | add // 0) | pct(3)), note: "Fees don't process themselves."},
    {label: "Loyalty Discount", amountCents: -1, note: "You're welcome."}
  ]) as $charges
| {
    itemCount: ([$c.lines[].qty] | add // 0),
    subtotalCents: $subtotal,
    charges: $charges,
    totalCents: ($subtotal + ([$charges[].amountCents] | add // 0))
  }

