def text(d; m): if type == "string" and length > 0 then .[0:m] else d end;
def obj: if type == "object" then . else {} end;
def int: floor % 1000000000000000;
def clamp(lo; hi; d): if type == "number" then (if . < lo then lo elif . > hi then hi else int end) else d end;

(.request | obj) as $r
| ($r.checkPauseSeconds | clamp(1; 5; 1)) as $pause
| ($r.oathWindowSeconds | clamp(1; 600; 60)) as $window
| {
    returnId: ($r.returnId | text("RMA-UNKNOWN"; 40)),
    seed: ($r.seed | if type == "number" then (if . < 0 then -. else . end | int) % 1000000 else 0 end),
    filedAt: ($r.filedAt | text("at a time nobody wrote down"; 40)),
    orderId: ($r.orderId | text("an order we cannot find"; 60)),
    orderFound: ($r.orderFound == true),
    customerName: ($r.customerName | text("Valued Customer #7"; 80)),
    item: ($r.item | obj | {
      id: (.id | text("mystery-item"; 60)),
      name: (.name | text("an item we will assume was a toaster"; 120)),
      emoji: (.emoji | text("📦"; 16)),
      priceCents: (.priceCents | if type == "number" and . >= 0 and . <= 99999999999 then int else 0 end)
    }),
    reason: ($r.reason | text("No reason given, which is itself a reason."; 200)),
    affidavit: ($r.affidavit | obj | {
      boxSmell: (.boxSmell | text("not described"; 200)),
      moonPhase: (.moonPhase | text("unknown"; 60)),
      regretSquares: (.regretSquares | clamp(0; 9; 0)),
      keepWillingness: (.keepWillingness | clamp(0; 100; 100))
    }),
    oathText: "I am sorry for what I did to the box.",
    checkPause: "\($pause)s",
    oathWindow: "\($window)s",
    oathWindowSeconds: $window,
    totalChecks: 6
  }

(.n | if type == "number" and . >= 1 then floor else 1 end) as $n
| .ret as $r
| [
    {
      department: "Bureau of Box Sniffing",
      name: "Olfactory audit of the cardboard",
      note: "Customer reports the box smelled \"\($r.affidavit.boxSmell)\". Our nose disagrees on principle."
    },
    {
      department: "Department of Lunar Compliance",
      name: "Moon phase cross-check",
      note: "Declared moon phase: \($r.affidavit.moonPhase). The moon declined to comment."
    },
    {
      department: "Office of Receipt Origami",
      name: "Verifying the receipt was folded correctly",
      note: "Receipt for \($r.orderId) was folded into a swan. Policy requires a crane."
    },
    {
      department: "Regret Authenticity Unit",
      name: "Measuring sincerity of regret",
      note: "Measured \($r.seed % 900 + 100) milliregrets across \($r.affidavit.regretSquares) declared squares of regret."
    },
    {
      department: "Committee for Asking a Guy Named Dale",
      name: "Dale is thinking about it",
      note: "Dale says he remembers \($r.item.name). Dale is thinking of a different item."
    },
    {
      department: "Division of Redundant Divisions Division",
      name: "Re-running check 1 to be sure",
      note: "Check 1 was re-run. The result was different. Both results stand."
    }
  ] as $checks
| ["PASS", "FAIL", "INCONCLUSIVE", "PASS (regrettably)", "FAIL (with distinction)"] as $verdicts
| $checks[(if $n > ($checks | length) then ($checks | length) else $n end) - 1]
  + {
      n: $n,
      total: ($checks | length),
      verdict: $verdicts[($r.seed + $n * 7) % ($verdicts | length)],
      consulted: false
    }

.ret as $r
| {
    creditCents: (($r.item.priceCents * 110 / 100 | ceil) % 1000000000000000),
    creditCode: "SORRY-\($r.seed)-NOTSORRY",
    terms: "Worth 110% of the item price. Valid only on items we do not sell. Expired yesterday."
  }

